/**
 * catalogue/html.ts — docs/catalogue/index.html: one static page over the generated catalogue (no network, no
 * libraries; open the file in a browser). Generated by `npm run catalogue`; never edit it by hand.
 */
import type { Catalogue, RegisterEntry } from "./build";
import type { InlinePrompt, InProcessCron, InternalRoute } from "./scan";

const esc = (s: unknown) => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const code = (s: unknown) => `<code>${esc(s)}</code>`;
const list = (xs: readonly string[]) => (xs.length ? xs.map(code).join(" ") : `<span class="muted">—</span>`);
const yes = (b: boolean) => (b ? `<span class="ok">yes</span>` : `<span class="muted">no</span>`);
const d12 = (s: string) => code(s.slice(0, 12));

function table(head: string[], rows: string[][]): string {
  return `<div class="scroll"><table><thead><tr>${head.map((h) => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${rows
    .map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
}

function section(id: string, title: string, count: number, intro: string, body: string): string {
  return `<section id="${id}"><h2>${esc(title)} <span class="count">${count}</span></h2><p class="intro">${intro}</p>${body}</section>`;
}

const statusTag = (s: string) => `<span class="tag t-${esc(s)}">${esc(s)}</span>`;

export function renderHtml(
  c: Catalogue,
  reg: { count: number; entries: RegisterEntry[] },
  lines: { crons: InProcessCron[]; prompts: InlinePrompt[]; routes: InternalRoute[] },
): string {
  const regById = new Map(reg.entries.map((e) => [e.id, e]));
  const promptText = (id: string) => {
    const e = regById.get(id);
    return e ? `<details><summary>text (${e.chars} chars)</summary><pre>${esc(e.text)}</pre></details>` : "";
  };
  const flagTable = (rows: Catalogue["flags"]["server"]) => {
    const srcs = rows.length ? Object.keys(rows[0].values) : [];
    return table(["name", "status", ...srcs, "read", "read in"], rows.map((f) => [
      code(f.name), statusTag(f.status), ...srcs.map((s) => (f.values[s] === null ? `<span class="muted">unset</span>` : code(f.values[s]))),
      esc(f.read), f.readIn.length > 3 ? `${list(f.readIn.slice(0, 3))} <span class="muted">+${f.readIn.length - 3}</span>` : list(f.readIn),
    ]));
  };
  const lineOf = <T extends { file: string; line: number }>(xs: T[], match: (x: T) => boolean) => xs.find(match)?.line;

  const sections = [
    section("core", "Mila core", c.core.files.length, `The numbered instruction files in ${code(c.core.dir + "/instructions")}, the surface parts, and the built instructions per surface (<code>buildMilaInstructions</code>).`,
      table(["file", "bytes", "sha256", "served chars"], c.core.files.map((f) => [code(f.file), String(f.bytes), d12(f.sha256), String(f.servedChars)]))
      + table(["part", "bytes", "sha256"], c.core.surfaces.map((f) => [code(f.file), String(f.bytes), d12(f.sha256)]))
      + `<h3>Built per surface</h3>` + table(["surface", "core files", "chars", "≈tokens", "sha256", "served text"], c.core.built.map((b) => [
        code(b.surface), b.coreFiles === "all" ? "all" : list(b.coreFiles), String(b.chars), String(b.approxTokens), d12(b.sha256), promptText(b.registerId)]))),
    section("skills", "Mila skills (playbooks)", c.skills.length, "Each <code>skills/&lt;name&gt;/SKILL.md</code> front-matter plus its <code>nomila.yaml</code>.",
      table(["name", "version", "register id", "surfaces", "flag", "tools", "sends externally", "lock", "description / text"], c.skills.map((s) => [
        code(s.name), esc(s.version), code(s.register_id), list(s.surfaces), s.flag ? code(s.flag) : `<span class="muted">—</span>`, list(s.tools),
        yes(s.sends_externally), s.lockMatches ? `<span class="ok">ok</span>` : `<span class="bad">stale</span>`, `${esc(s.description)}${promptText(s.register_id)}`]))),
    section("jobs", "Job prompts", c.jobs.items.length, `Every prompt the job loader (${code(c.jobs.loader)}, files in ${code(c.jobs.dir)}) serves; the digest is <code>promptDigest</code>, recorded on every run.`,
      table(["id", "version", "model tier", "effort", "tools", "promptDigest", "description / text"], c.jobs.items.map((j) => [
        code(j.id), esc(j.version), code(j.model), esc(j.effort), list(j.tools), d12(j.promptDigest), `${esc(j.description)}${promptText(`job.${j.id}`)}`]))),
    section("tools", "Tools", c.tools.length, `Every registry tool (<code>passRegistry()</code>, what <code>engine/mastra/tools.ts</code> wraps). <strong>${c.tools.filter((t) => t.milaCallable).length}</strong> are callable by a Mila pass; display rules from <code>engine/mastra/display.ts</code>, card DTOs from <code>shared/milaCards.ts</code>.`,
      table(["name", "permission", "Mila passes", "display rule", "card types (DTO)", "sends externally (act)", "in a sending playbook", "flag-gated", "description"], c.tools.map((t) => [
        code(t.name), statusTag(t.permission), t.milaCallable ? list(t.passes) : `<span class="muted">not callable</span>`,
        t.milaCallable ? (t.displayRule ? `<span class="ok">yes</span>` : `<span class="bad">MISSING</span>`) : yes(t.displayRule),
        t.cardTypes.length ? t.cardTypes.map((k) => (t.cardDtos.includes(k) ? code(k) : `<span class="bad">${esc(k)} (no DTO)</span>`)).join(" ") : `<span class="muted">—</span>`,
        yes(t.sends_externally), yes(t.inSendingPlaybook), yes(t.flagGated), `<span class="desc">${esc(t.description)}</span>`]))),
    section("cards", "Cards", c.cards.length, "The DTO types chat v2 sends (<code>shared/milaCards.ts</code>), their own fields and the tools that make them.",
      table(["type", "fields", "made by"], c.cards.map((k) => [code(k.type), Object.entries(k.fields).map(([f, t]) => `${code(f)}: <span class="muted">${esc(t)}</span>`).join("<br>"), list(k.madeBy)]))),
    section("flags", "Flags", c.flags.server.length + c.flags.client.length, `Server: every <code>process.env.*</code> read in <code>server/</code> and <code>shared/</code> (direct, or a name handed to a config helper) against ${esc(c.flags.sources.server)}. Client: every <code>EXPO_PUBLIC_*</code> in <code>client/</code> against ${esc(c.flags.sources.client)}. ${statusTag("always-on")} on everywhere listed, ${statusTag("never-on")} on nowhere, ${statusTag("inverted")} on unless set to "false", ${statusTag("unread")} set but no read found, ${statusTag("script")} read only by a one-off script under server/scripts.`,
      `<h3>Server (${c.flags.server.length})</h3>${flagTable(c.flags.server)}<h3>Client (${c.flags.client.length})</h3>${flagTable(c.flags.client)}`),
    section("workflows", "Workflows", c.workflows.length, "Registered by <code>server/workflow/definitions</code> (the Postgres runner); steps as name:kind.",
      table(["process", "default", "versions and steps"], c.workflows.map((w) => [code(w.process), w.defaultVersion === null ? "—" : `v${w.defaultVersion}`,
        w.versions.map((v) => `<b>v${v.version}</b> ${v.steps.map(code).join(" → ")}`).join("<br>")]))),
    section("crons", "Internal routes, scheduler jobs and in-process crons", c.internalRoutes.length + c.schedulerJobs.length + c.inProcessCrons.length, "Routes under <code>/api/internal/</code>; the Cloud Scheduler jobs declared in <code>scripts/provision-schedulers.sh</code>; <code>node-cron</code> schedules inside the server.",
      `<h3>Cloud Scheduler jobs (${c.schedulerJobs.length})</h3>` + table(["job", "schedule", "path", "deadline", "route in server"], c.schedulerJobs.map((j) => [code(j.name), code(j.schedule), code(j.path), esc(j.deadline), j.routeFound ? `<span class="ok">yes</span>` : `<span class="bad">not found</span>`]))
      + `<h3>/api/internal routes (${c.internalRoutes.length})</h3>` + table(["method", "path", "file:line"], c.internalRoutes.map((r) => [esc(r.method), code(r.path), code(`${r.file}:${lineOf(lines.routes, (x) => x.path === r.path && x.file === r.file && x.method === r.method) ?? "?"}`)]))
      + `<h3>In-process crons (${c.inProcessCrons.length})</h3>` + table(["schedule", "runs", "only when", "file:line"], lines.crons.map((x) => [code(x.schedule), list(x.runs), x.gatedBy.map(code).join(" &amp;&amp; ") || "always", code(`${x.file}:${x.line}`)]))),
    section("inline", "Inline prompts (TODO)", c.inlinePrompts.length, `A heuristic list: string literals over 400 characters in <code>server/</code> and <code>shared/</code> .ts files that read like a model prompt. Each is a candidate to move into a versioned, registered prompt file. Prompts built with <code>[…].join()</code> are not found.`,
      table(["file:line", "where", "chars", "digest", "starts"], lines.prompts.map((p) => [code(`${p.file}:${p.line}`), code(p.anchor), String(p.chars), code(p.digest), `<span class="desc">${esc(p.preview)}…</span>`]))),
  ];

  const nav = [["core", "Core", c.core.files.length], ["skills", "Skills", c.skills.length], ["jobs", "Job prompts", c.jobs.items.length], ["tools", "Tools", c.tools.length],
    ["cards", "Cards", c.cards.length], ["flags", "Flags", c.flags.server.length + c.flags.client.length], ["workflows", "Workflows", c.workflows.length],
    ["crons", "Routes & crons", c.internalRoutes.length + c.schedulerJobs.length + c.inProcessCrons.length], ["inline", "Inline prompts", c.inlinePrompts.length]] as const;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Nomila catalogue</title>
<style>
:root { --bg:#fbfaf8; --fg:#1d1c1a; --muted:#77736c; --line:#e6e2db; --card:#fff; --accent:#7a4e2d; --ok:#2f7a3b; --bad:#b3261e; --tag:#f0ece6; }
@media (prefers-color-scheme: dark) { :root { --bg:#161513; --fg:#ecebe8; --muted:#9c978f; --line:#2f2c28; --card:#1e1c1a; --accent:#e0a878; --ok:#7cc488; --bad:#ff8a80; --tag:#2a2724; } }
* { box-sizing:border-box; }
body { margin:0; background:var(--bg); color:var(--fg); font:14px/1.5 system-ui,-apple-system,"Segoe UI",sans-serif; }
header { position:sticky; top:0; z-index:2; background:var(--bg); border-bottom:1px solid var(--line); padding:12px 16px; }
header h1 { margin:0 0 6px; font-size:18px; }
nav { display:flex; flex-wrap:wrap; gap:6px; }
nav a { color:var(--fg); text-decoration:none; background:var(--tag); border-radius:999px; padding:2px 10px; font-size:13px; }
nav a b { color:var(--accent); margin-left:4px; }
#q { margin-top:8px; width:100%; max-width:420px; padding:6px 10px; border:1px solid var(--line); border-radius:8px; background:var(--card); color:var(--fg); }
main { padding:8px 16px 48px; max-width:1500px; }
section { margin-top:28px; }
h2 { font-size:17px; margin:0 0 4px; } h3 { font-size:14px; margin:16px 0 6px; color:var(--muted); }
.count { color:var(--accent); font-weight:600; margin-left:6px; }
.intro { margin:0 0 8px; color:var(--muted); max-width:900px; }
.scroll { overflow-x:auto; border:1px solid var(--line); border-radius:8px; background:var(--card); }
table { border-collapse:collapse; width:100%; }
th, td { text-align:left; vertical-align:top; padding:6px 8px; border-bottom:1px solid var(--line); }
th { position:sticky; top:0; background:var(--card); font-weight:600; white-space:nowrap; }
code { font:12px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace; background:var(--tag); border-radius:4px; padding:0 4px; word-break:break-word; }
pre { white-space:pre-wrap; font:12px/1.45 ui-monospace,Consolas,monospace; max-height:420px; overflow:auto; background:var(--tag); padding:8px; border-radius:6px; }
.muted { color:var(--muted); } .ok { color:var(--ok); } .bad { color:var(--bad); font-weight:600; }
.desc { display:block; max-width:520px; }
.tag { display:inline-block; border-radius:4px; padding:0 6px; font-size:12px; background:var(--tag); white-space:nowrap; }
.t-always-on, .t-act { color:var(--accent); } .t-never-on, .t-unread { color:var(--bad); } .t-inverted { color:#8a5cd0; }
tr.hide { display:none; }
</style>
</head>
<body>
<header>
<h1>Nomila catalogue</h1>
<nav>${nav.map(([id, label, n]) => `<a href="#${id}">${esc(label)}<b>${n}</b></a>`).join("")}<a href="prompt-register.json">Prompt Register<b>${reg.count}</b></a><a href="catalogue.json">catalogue.json</a></nav>
<input id="q" type="search" placeholder="Filter rows (name, file, flag…)" aria-label="Filter rows">
</header>
<main>
<p class="muted">Generated by <code>npm run catalogue</code> (scripts/catalogue/build.ts) from the repo itself. Do not edit by hand; regenerate. Line numbers are as of generation and are not part of the checked JSON.</p>
${sections.join("\n")}
</main>
<script>
(function () {
  var q = document.getElementById("q");
  q.addEventListener("input", function () {
    var v = q.value.toLowerCase();
    document.querySelectorAll("tbody tr").forEach(function (tr) { tr.classList.toggle("hide", !!v && tr.textContent.toLowerCase().indexOf(v) < 0); });
  });
})();
</script>
</body>
</html>
`;
}
